def cached(cache, key=keys.hashkey, lock=None, info=False, condition=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """

    def decorator(func):
        w = _cached_wrapper(
            func,
            cache,
            key,
            lock,
            (
                (lambda h, m: _CacheInfo(h, m, cache.maxsize, cache.currsize))
                if isinstance(cache, Cache)
                else (lambda h, m: _CacheInfo(h, m, None, len(cache)))
                if isinstance(cache, collections.abc.Mapping)
                else (lambda h, m: _CacheInfo(h, m, 0, 0))
            )
            if info
            else None,
            condition,
        )
        w.cache = cache
        w.cache_key = key
        w.cache_lock = lock
        return functools.update_wrapper(w, func)

    return decorator
