def _cached_condition_info(func, cache, key, cond, info):
    """Wrapper using threading.Condition for stampede protection."""
    h = m = 0
    prog = set()

    def w(*args, **kwargs):
        nonlocal h, m
        k = key(*args, **kwargs)
        with cond:
            try:
                v = cache[k]
                h += 1
                return v
            except KeyError:
                pass
            if k in prog:
