                        except KeyError:
                            pass
                    prog.add(k)
                v = method(self, *args, **kwargs)
                with cond:
                    try:
                        c[k] = v
                    except ValueError:
                        prog.discard(k)
                        cond.notify_all()
                        return v
                    prog.discard(k)
                    cond.notify_all()
                    return v

