def _cached_condition_info(func, cache, key, cond, info):
    '''Wrapper using threading.Condition for stampede protection.'''
    h = m = 0
    prog = set()

    def w(*args, **kwargs):
        nonlocal h, m
        k = key(*args, **kwargs)
        with cond:
            try:
                v = cache[k]
                h += 1
                return v
            except KeyError:
                pass
            if k in prog:
                cond.wait()
                try:
                    v = cache[k]
                    h += 1
                    return v
                except KeyError:
                    pass
            m += 1
            prog.add(k)
        v = func(*args, **kwargs)
        with cond:
            try:
                cache[k] = v
            except ValueError:
                prog.discard(k)
                cond.notify_all()
                return v
            prog.discard(k)
            cond.notify_all()
            return v

    def cache_clear():
        nonlocal h, m
        with cond:
            cache.clear()
            prog.clear()
            h = m = 0

    def cache_info():
        with cond:
            return info(h, m)

    w.cache_clear = cache_clear
    w.cache_info = cache_info
    return w
