def cachedmethod(cache, key=keys.methodkey, lock=None, condition=None):
    '''Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    '''

    def decorator(method):
        if condition is not None:

            def w(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                cond = condition(self) if callable(condition) else condition
                with cond:
                    try:
                        return c[k]
                    except KeyError:
                        pass
                    if not hasattr(c, '_in_progress'):
                        c._in_progress = set()
                    prog = c._in_progress
                    if k in prog:
                        cond.wait()
                        try:
                            return c[k]
                        except KeyError:
                            pass
                    prog.add(k)
                v = method(self, *args, **kwargs)
                with cond:
                    try:
                        c[k] = v
                    except ValueError:
                        prog.discard(k)
                        cond.notify_all()
                        return v
                    prog.discard(k)
                    cond.notify_all()
                    return v

            def clear(self):
                c = cache(self)
                if c is not None:
                    cond = condition(self) if callable(condition) else condition
                    with cond:
                        c.clear()
                        if hasattr(c, '_in_progress'):
                            c._in_progress.clear()

        elif lock is None:

            def w(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass
                return v

            def clear(self):
                c = cache(self)
                if c is not None:
                    c.clear()

        else:

            def w(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        return c.setdefault(k, v)
                except ValueError:
                    return v

            def clear(self):
                c = cache(self)
                if c is not None:
                    with lock(self):
                        c.clear()

        w.cache = cache
        w.cache_key = key
        w.cache_lock = lock
        w.cache_clear = clear
        return functools.update_wrapper(w, method)

    return decorator
